                /**
                 * Uložení informací o aktuálním (do kterého se vstupuje) kroku
                 *
                 * @param {number} faze poslední (uložená) fáze
                 * @param {Wizard.changeObject} change informace o kroku průvodce
                 * @returns {number} aktuální fáze
                 */
                function saveStepInfo(faze, change) {
                    // TODO: doplnit správný typ pro change
                    // krok, do kterého vstupujeme, je buď v change.task.nextStep nebo v change.activeStep
                    let actStep = (typeof change.task.nextStep === "undefined" ? change.activeStep : change.task.nextStep);
                    if ((actStep >= 0) && (actStep <= 2)) {
                        for (let i = 0; i <= 2; i++) {
                            // povolené jsou všechny kroky kromě z prvního na poslední a z posledního na předchozí
                            if (i == actStep)
                                change.stepsEnable[i] = true;
                            else if ((i == actStep - 1) && (actStep < 2))
                                change.stepsEnable[i] = true;
                            else if (i == actStep + 1)
                                change.stepsEnable[i] = true;
                            else
                                change.stepsEnable[i] = false;
                        }
                        // informace o předchozím a aktuálním kroku
                        return actStep;
                    }
                    else
                        return faze;
                }
                FucWizard.saveStepInfo = saveStepInfo;
